arguments.command:
cd /home/azureuser/sonic-dev/recodeAgent/pipeline/logs && mkdir -p /tmp/recon && python3 - <<'PY'
import json,re,base64,gzip,io
runs=[]
with open('analyzer.stdout.jsonl') as f:
    for i,line in enumerate(f):
        for m in re.finditer(r'[A-Za-z0-9+/]{500,}={0,2}', line):
            runs.append((len(m.group(0)), i, m.group(0)))
runs.sort(reverse=True)
for ln,i,s in runs[:6]:
    try:
        raw=base64.b64decode(s)
        magic=raw[:2]
        isgz = magic==b'\x1f\x8b'
        print(f"line {i} len_b64={ln} decoded={len(raw)} gzip={isgz} head={raw[:8]!r}")
        if isgz:
            data=gzip.decompress(raw)
            print("  -> gunzip ok, bytes:",len(data),"tar_magic@257:",data[257:262])
    except Exception as e:
        print(f"line {i} len={ln} decode_err={e}")
PY

