#!/usr/bin/env python3
"""Generate the xcvrd-rs Rust skeleton (compilable stubs + mock/test seams)
mirroring the Python xcvrd package layout. Writes under pipeline/crate/xcvrd-rs/src.
Idempotent: overwrites the generated stub files only (leaves env.rs/daemon.rs/main.rs).
"""
import os, re, json

SRC = "/home/azureuser/sonic-dev/recodeAgent/pipeline/crate/xcvrd-rs/src"
PYSRC = "/tmp/xsrc/src"

def w(rel, text):
    path = os.path.join(SRC, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        f.write(text.rstrip() + "\n")
    print("wrote", rel)

# ---- collect the 187 Python test names and map each to a Rust module -------
def test_names():
    p = os.path.join(PYSRC, "tests/test_xcvrd.py")
    names = []
    with open(p) as f:
        for ln in f:
            m = re.match(r"\s*def (test_\w+)\(", ln)
            if m:
                names.append(m.group(1))
    return names

def classify(t):
    """Map a Python test_xcvrd.py case to (rust_module_relpath)."""
    def has(*subs): return any(s in t for s in subs)
    if t.startswith("test_SffManagerTask") or t.startswith("test_sff"):
        return "sff_mgr.rs"
    if t.startswith("test_CmisManagerTask") or t.startswith("test_cmis"):
        return "cmis/cmis_manager_task.rs"
    if t.startswith("test_DomThermalInfoUpdateTask") or t.startswith("test_DomInfoUpdateTask"):
        return "dom/dom_mgr.rs"
    if has("post_port_pm_info", "post_port_sfp_firmware_info"):
        return "dom/dom_mgr.rs"
    if has("post_port_dom_sensor", "post_port_dom_temperature", "get_transceiver_dom_sensor",
           "get_transceiver_dom_temperature", "beautify_dom_info"):
        return "dom/utilities/dom_sensor/db_utils.rs"
    if has("post_port_dom_flags", "post_port_dom_thresholds", "get_transceiver_dom_flags",
           "get_transceiver_dom_thresholds"):
        return "dom/utilities/dom_sensor/db_utils.rs"
    if has("update_flag_metadata_tables", "beautify_info_dict", "get_current_time"):
        return "dom/utilities/db/utils.rs"
    if has("post_port_transceiver_hw_status", "get_transceiver_status"):
        return "dom/utilities/status/db_utils.rs"
    if has("post_port_vdm", "get_vdm", "is_vdm_statistic", "vdm_action",
           "is_transceiver_vdm_supported"):
        return "dom/utilities/vdm/db_utils.rs"
    if has("detect_port_in_error_status", "is_error_sfp_status"):
        return "xcvrd_utilities/sfp_status_helper.rs"
    if has("handle_port_update_event", "handle_port_config_change", "get_port_mapping",
           "handle_front_panel_filter"):
        return "xcvrd_utilities/port_event_helper.rs"
    if has("get_state_db_port_table_val_by_key", "is_npu_si_settings_update_required",
           "XcvrTableHelper"):
        return "xcvrd_utilities/xcvr_table_helper.rs"
    if has("optics_si", "optical_si", "get_module_vendor_key", "match_optics_si",
           "get_port_media_settings", "get_global_media_settings"):
        return "xcvrd_utilities/optics_si_parser.rs"
    if has("media_settings", "notify_media_setting", "custom_media", "is_si_per_speed",
           "get_speed_lane_count_and_subport", "media_settings_parser"):
        return "xcvrd_utilities/media_settings_parser.rs"
    if has("xcvrd_utils", "is_transceiver_flat_memory", "is_transceiver_lpmode_on"):
        return "xcvrd_utilities/utils.rs"
    if has("del_port_sfp_dom_info_from_db", "is_cmis_api", "get_cmis_state_from_state_db",
           "is_syncd_warm_restore", "is_copper", "get_interface_speed",
           "wrapper_get_presence", "check_port_in_range"):
        return "xcvrd_utilities/common.rs"
    # remaining wrappers + daemon + SfpStateUpdateTask + DaemonXcvrd
    return "xcvrd.rs"

TESTS = test_names()
BYMOD = {}
for t in TESTS:
    BYMOD.setdefault(classify(t), []).append(t)

def test_mod(names, extra_pass=True):
    """Render a #[cfg(test)] mod tests with #[ignore] stubs mirroring Python tests."""
    lines = ["", "#[cfg(test)]", "mod tests {", "    #[allow(unused_imports)]", "    use super::*;", ""]
    if extra_pass:
        lines += ["    #[test]",
                  "    fn skeleton_present() {",
                  "        // Sanity: the module compiles and is wired into the crate.",
                  "        assert!(true);",
                  "    }", ""]
    for n in names:
        lines += [f'    #[test]',
                  f'    #[ignore = "stub: translate {n} from tests/test_xcvrd.py"]',
                  f'    fn {n}() {{',
                  f'        // TODO(Part B): port tests/test_xcvrd.py::{n} using MockChassis/MockTable.',
                  f'    }}',
                  ""]
    lines.append("}")
    return "\n".join(lines)

